WITH history AS (SELECT DATE_TRUNC(`event_date`, DAY) AS period, COUNT(*) AS cnt FROM `fake_project.dataset.orders` WHERE `event_date` >= DATE('2026-05-01') - INTERVAL 28 DAY AND `event_date` < DATE('2026-05-01') GROUP BY period), medians AS (SELECT PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY cnt) AS median FROM history) SELECT (SELECT median FROM medians) AS median, PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY ABS(cnt - (SELECT median FROM medians))) AS mad, COUNT(*) AS n FROM history